//! Differential ratchet for `src/engine/battleScriptSetyawnOpcode.ts`.
//! Expected complete projected results, controls, and the exact missing-role
//! error are generated by invoking the canonical TypeScript opcode handler;
//! regenerate with `node --experimental-strip-types
//! core-rs/tools/gen-battle-script-setyawn-vectors.mjs`.

use std::collections::BTreeSet;

use factory_core::battle_script_setyawn::{
    apply_battle_script_setyawn, BattleScriptSetyawnBattlerState, BattleScriptSetyawnControl,
    BattleScriptSetyawnRoles, BattleScriptSetyawnRules, BATTLE_SCRIPT_SETYAWN_BATTLERS,
    BATTLE_SCRIPT_SETYAWN_BATTLER_COUNT, BATTLE_SCRIPT_STATUS1_ANY, BATTLE_SCRIPT_STATUS1_BURN,
    BATTLE_SCRIPT_STATUS1_FREEZE, BATTLE_SCRIPT_STATUS1_PARALYSIS, BATTLE_SCRIPT_STATUS1_POISON,
    BATTLE_SCRIPT_STATUS1_SLEEP, BATTLE_SCRIPT_STATUS1_TOXIC_POISON, BATTLE_SCRIPT_STATUS3_YAWN,
    BATTLE_SCRIPT_STATUS3_YAWN_TURN_2,
};
use factory_core::battle_script_setyawn_vectors_gen::{
    BattleScriptSetyawnVectorCase, BattleScriptSetyawnVectorState,
    BATTLE_SCRIPT_SETYAWN_BATTLER_DOMAIN, BATTLE_SCRIPT_SETYAWN_BRANCH_CENSUS,
    BATTLE_SCRIPT_SETYAWN_CASES, BATTLE_SCRIPT_SETYAWN_CATEGORY_CENSUS,
    BATTLE_SCRIPT_SETYAWN_DOMAIN_CENSUS, BATTLE_SCRIPT_SETYAWN_STATUS1_ANY_MEMBER_DOMAIN,
    BATTLE_SCRIPT_SETYAWN_STATUS1_EDGE_DOMAIN, BATTLE_SCRIPT_SETYAWN_STATUS3_EDGE_DOMAIN,
    BATTLE_SCRIPT_SETYAWN_VECTOR_CORPUS_SHA256, BATTLE_SCRIPT_SETYAWN_YAWN_COUNTER_DOMAIN,
    BATTLE_SCRIPT_SETYAWN_YAWN_PACKED_DOMAIN,
};

fn rules(value: BattleScriptSetyawnVectorState) -> BattleScriptSetyawnRules {
    BattleScriptSetyawnRules {
        battlers: core::array::from_fn(|index| BattleScriptSetyawnBattlerState {
            status1: value.status1[index],
            status3: value.status3[index],
        }),
        selector_roles: BattleScriptSetyawnRoles { target: value.target },
    }
}

fn vector_state(value: BattleScriptSetyawnRules) -> BattleScriptSetyawnVectorState {
    BattleScriptSetyawnVectorState {
        status1: value.battlers.map(|battler| battler.status1),
        status3: value.battlers.map(|battler| battler.status3),
        target: value.selector_roles.target,
    }
}

#[test]
fn complete_projected_outputs_controls_and_exact_error_match_canonical_typescript() {
    assert_eq!(BATTLE_SCRIPT_SETYAWN_CASES.len(), 96);
    for (case_index, case) in BATTLE_SCRIPT_SETYAWN_CASES.iter().enumerate() {
        execute_case(case_index, case);
    }
}

fn execute_case(case_index: usize, case: &BattleScriptSetyawnVectorCase) {
    let input = rules(case.initial);
    let before = input;
    let mut current = input;
    let mut actual_controls = Vec::new();
    let mut actual_error = None;

    for application in 0..case.applications {
        let prior = current;
        match apply_battle_script_setyawn(&current) {
            Ok(outcome) => {
                actual_controls.push(outcome.control);
                assert_transition_shape(case_index, case, application, prior, outcome);
                current = outcome.rules;
            }
            Err(error) => {
                actual_error = Some(error.to_string());
                break;
            }
        }
    }

    assert_eq!(
        input, before,
        "case {case_index} {}: native transformation mutated input",
        case.label,
    );
    match (actual_error, case.expected, case.expected_error) {
        (None, Some(expected), None) => {
            assert_eq!(
                actual_controls.as_slice(),
                case.controls,
                "case {case_index} {}: canonical control sequence",
                case.label,
            );
            assert_eq!(
                actual_controls.len(),
                usize::from(case.applications),
                "case {case_index} {}: successful sequence stopped early",
                case.label,
            );
            assert_eq!(
                vector_state(current),
                expected,
                "case {case_index} {}: complete projected output",
                case.label,
            );
        }
        (Some(error), None, Some(expected_error)) => {
            assert_eq!(
                actual_controls.as_slice(),
                case.controls,
                "case {case_index} {}: error must not produce a control result",
                case.label,
            );
            assert_eq!(
                error, expected_error,
                "case {case_index} {}: exact missing-target error",
                case.label,
            );
        }
        (error, expected, expected_error) => panic!(
            "case {case_index} {}: generated outcome shape disagrees with native result: error={error:?}, expected={expected:?}, expected_error={expected_error:?}",
            case.label,
        ),
    }
}

fn assert_transition_shape(
    case_index: usize,
    case: &BattleScriptSetyawnVectorCase,
    application: u8,
    prior: BattleScriptSetyawnRules,
    outcome: factory_core::battle_script_setyawn::BattleScriptSetyawnOutcome,
) {
    match outcome.control {
        BattleScriptSetyawnControl::FailJump => {
            assert_eq!(
                outcome.rules, prior,
                "case {case_index} {} application {application}: fail jump changed complete state",
                case.label,
            );
        }
        BattleScriptSetyawnControl::Advance => {
            let target = prior.selector_roles.target.unwrap_or_else(|| {
                panic!(
                    "case {case_index} {} application {application}: advance had no target",
                    case.label,
                )
            });
            assert_eq!(
                outcome.rules.selector_roles, prior.selector_roles,
                "case {case_index} {} application {application}: changed target role",
                case.label,
            );
            for battler in BATTLE_SCRIPT_SETYAWN_BATTLERS {
                if battler != target {
                    assert_eq!(
                        outcome.rules.battlers[battler.index()],
                        prior.battlers[battler.index()],
                        "case {case_index} {} application {application}: changed non-target battler {}",
                        case.label,
                        battler.as_u8(),
                    );
                }
            }
            let prior_target = prior.battlers[target.index()];
            let next_target = outcome.rules.battlers[target.index()];
            assert_eq!(
                next_target.status1, prior_target.status1,
                "case {case_index} {} application {application}: changed target status1",
                case.label,
            );
            assert_eq!(
                next_target.status3,
                prior_target.status3 | BATTLE_SCRIPT_STATUS3_YAWN_TURN_2,
                "case {case_index} {} application {application}: did not OR turn-2 Yawn into target",
                case.label,
            );
            assert_eq!(
                next_target.status3 & !BATTLE_SCRIPT_STATUS3_YAWN,
                prior_target.status3 & !BATTLE_SCRIPT_STATUS3_YAWN,
                "case {case_index} {} application {application}: changed target status3 unrelated bits",
                case.label,
            );
            assert_eq!(
                next_target.status3 & BATTLE_SCRIPT_STATUS3_YAWN,
                BATTLE_SCRIPT_STATUS3_YAWN_TURN_2,
                "case {case_index} {} application {application}: wrong packed Yawn counter",
                case.label,
            );
        }
    }
}

#[test]
fn counter_and_status1_member_matrices_cover_every_target_and_exact_mask_member() {
    let counter_matrix = BATTLE_SCRIPT_SETYAWN_CASES
        .iter()
        .filter(|case| case.category == "target-yawn-counter-matrix")
        .collect::<Vec<_>>();
    assert_eq!(counter_matrix.len(), 16);
    let counters = counter_matrix
        .iter()
        .map(|case| {
            let target = case
                .initial
                .target
                .unwrap_or_else(|| panic!("counter case {} has no target", case.label));
            (
                target.as_u8(),
                ((case.initial.status3[target.index()] & BATTLE_SCRIPT_STATUS3_YAWN) >> 11) as u8,
            )
        })
        .collect::<BTreeSet<_>>();
    let expected_counters = BATTLE_SCRIPT_SETYAWN_BATTLER_DOMAIN
        .into_iter()
        .flat_map(|target| {
            BATTLE_SCRIPT_SETYAWN_YAWN_COUNTER_DOMAIN
                .into_iter()
                .map(move |counter| (target, counter))
        })
        .collect::<BTreeSet<_>>();
    assert_eq!(counters, expected_counters);

    let member_matrix = BATTLE_SCRIPT_SETYAWN_CASES
        .iter()
        .filter(|case| case.category == "target-status1-any-member-matrix")
        .collect::<Vec<_>>();
    assert_eq!(member_matrix.len(), 32);
    let members = member_matrix
        .iter()
        .map(|case| {
            let target = case
                .initial
                .target
                .unwrap_or_else(|| panic!("status1 member case {} has no target", case.label));
            (
                target.as_u8(),
                case.initial.status1[target.index()] & BATTLE_SCRIPT_STATUS1_ANY,
            )
        })
        .collect::<BTreeSet<_>>();
    let expected_members = BATTLE_SCRIPT_SETYAWN_BATTLER_DOMAIN
        .into_iter()
        .flat_map(|target| {
            BATTLE_SCRIPT_SETYAWN_STATUS1_ANY_MEMBER_DOMAIN
                .into_iter()
                .map(move |member| (target, member))
        })
        .collect::<BTreeSet<_>>();
    assert_eq!(members, expected_members);
    assert_eq!(
        BATTLE_SCRIPT_SETYAWN_STATUS1_ANY_MEMBER_DOMAIN,
        [
            0x0000_0001,
            0x0000_0002,
            0x0000_0004,
            BATTLE_SCRIPT_STATUS1_POISON,
            BATTLE_SCRIPT_STATUS1_BURN,
            BATTLE_SCRIPT_STATUS1_FREEZE,
            BATTLE_SCRIPT_STATUS1_PARALYSIS,
            BATTLE_SCRIPT_STATUS1_TOXIC_POISON,
        ],
    );
}

#[test]
fn missing_target_precedes_status_checks_and_or_paths_preserve_complete_state() {
    let missing = BATTLE_SCRIPT_SETYAWN_CASES
        .iter()
        .find(|case| case.label == "missing_target_precedes_status_checks")
        .expect("missing target-order vector");
    assert_eq!(missing.initial.target, None);
    assert_ne!(missing.initial.status1[2] & BATTLE_SCRIPT_STATUS1_ANY, 0);
    assert_ne!(missing.initial.status3[2] & BATTLE_SCRIPT_STATUS3_YAWN, 0);
    assert_eq!(missing.expected, None);
    assert!(missing.controls.is_empty());
    assert_eq!(
        missing.expected_error,
        Some("Cmd_setyawn requires a target role"),
    );

    let combinations = BATTLE_SCRIPT_SETYAWN_CASES
        .iter()
        .filter(|case| case.category == "or-short-circuit-combinations")
        .collect::<Vec<_>>();
    assert_eq!(combinations.len(), 12);
    let mut yawn_only = 0;
    let mut status1_only = 0;
    let mut both = 0;
    for case in combinations {
        let target = case
            .initial
            .target
            .unwrap_or_else(|| panic!("OR case {} has no target", case.label));
        let has_yawn = case.initial.status3[target.index()] & BATTLE_SCRIPT_STATUS3_YAWN != 0;
        let has_status1 = case.initial.status1[target.index()] & BATTLE_SCRIPT_STATUS1_ANY != 0;
        match (has_yawn, has_status1) {
            (true, false) => yawn_only += 1,
            (false, true) => status1_only += 1,
            (true, true) => both += 1,
            (false, false) => panic!("OR case {} has neither failure condition", case.label),
        }
        assert_eq!(case.controls, &[BattleScriptSetyawnControl::FailJump]);
        assert_eq!(case.expected, Some(case.initial));
    }
    assert_eq!((yawn_only, status1_only, both), (4, 4, 4));

    let repeated_success = BATTLE_SCRIPT_SETYAWN_CASES
        .iter()
        .find(|case| case.label == "repeated_success_then_fail")
        .expect("missing repeated success vector");
    assert_eq!(
        repeated_success.controls,
        &[
            BattleScriptSetyawnControl::Advance,
            BattleScriptSetyawnControl::FailJump,
        ],
    );
    let repeated_failure = BATTLE_SCRIPT_SETYAWN_CASES
        .iter()
        .find(|case| case.label == "repeated_fail_remains_unchanged")
        .expect("missing repeated failure vector");
    assert_eq!(
        repeated_failure.controls,
        &[
            BattleScriptSetyawnControl::FailJump,
            BattleScriptSetyawnControl::FailJump,
        ],
    );
    assert_eq!(repeated_failure.expected, Some(repeated_failure.initial));
}

#[test]
fn fixed_domains_u32_edges_and_source_constants_are_retained() {
    assert_eq!(BATTLE_SCRIPT_SETYAWN_BATTLER_COUNT, 4);
    assert_eq!(
        BATTLE_SCRIPT_SETYAWN_BATTLERS.map(|battler| battler.as_u8()),
        BATTLE_SCRIPT_SETYAWN_BATTLER_DOMAIN,
    );
    assert_eq!(BATTLE_SCRIPT_SETYAWN_BATTLER_DOMAIN, [0, 1, 2, 3]);
    assert_eq!(BATTLE_SCRIPT_STATUS1_SLEEP, 0x0000_0007);
    assert_eq!(BATTLE_SCRIPT_STATUS1_ANY, 0x0000_00ff);
    assert_eq!(BATTLE_SCRIPT_STATUS3_YAWN, 0x0000_1800);
    assert_eq!(BATTLE_SCRIPT_STATUS3_YAWN_TURN_2, 0x0000_1000);
    assert_eq!(
        BATTLE_SCRIPT_SETYAWN_STATUS1_EDGE_DOMAIN,
        [0x0000_0000, u32::MAX, 0x8000_0000, 0x0000_0100],
    );
    assert_eq!(
        BATTLE_SCRIPT_SETYAWN_STATUS3_EDGE_DOMAIN,
        [0x0000_0000, u32::MAX, 0x8000_0000, 0x0000_0001],
    );
    assert_eq!(BATTLE_SCRIPT_SETYAWN_YAWN_COUNTER_DOMAIN, [0, 1, 2, 3]);
    assert_eq!(
        BATTLE_SCRIPT_SETYAWN_YAWN_PACKED_DOMAIN,
        [0x0000_0000, 0x0000_0800, 0x0000_1000, 0x0000_1800],
    );
}

#[test]
fn domain_category_branch_censuses_and_corpus_hash_are_ratchet_pinned() {
    assert_eq!(
        BATTLE_SCRIPT_SETYAWN_DOMAIN_CENSUS,
        [
            ("battler-slots", 4),
            ("target-role-values", 4),
            ("optional-target-role-values", 5),
            ("status1-u32-values", 4_294_967_296),
            ("status3-u32-values", 4_294_967_296),
            ("status1-any-member-values", 8),
            ("status1-any-mask", 255),
            ("status1-edge-values", 4),
            ("status3-edge-values", 4),
            ("yawn-counter-values", 4),
            ("yawn-packed-field-values", 4),
            ("application-count-values", 2),
            ("typed-missing-target-combinations", 1),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_SETYAWN_CATEGORY_CENSUS,
        [
            ("missing-target-role", 1),
            ("or-short-circuit-combinations", 12),
            ("repeated-application", 2),
            ("status1-u32-edge-matrix", 16),
            ("status3-u32-edge-matrix", 16),
            ("target-only-mutation", 1),
            ("target-status1-any-member-matrix", 32),
            ("target-yawn-counter-matrix", 16),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_SETYAWN_BRANCH_CENSUS,
        [
            ("advance", 29),
            ("advance-then-fail-jump", 1),
            ("fail-jump", 64),
            ("fail-jump-then-fail-jump", 1),
            ("missing-target-role", 1),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_SETYAWN_VECTOR_CORPUS_SHA256,
        "bfaba855da35331383adfd4281e1194e16eb8bb66e3a800e81b733bfd511de79",
    );
}
